import axios from "axios";
import {
  collection,
  getDocs,
  addDoc,
  updateDoc,
  deleteDoc,
  doc,
  query,
  where,
  orderBy,
  Timestamp,
  QueryConstraint,
  deleteField
} from "firebase/firestore";
import { authService } from "./authService";

export interface BaseModel {
  _id: string | undefined;
  createdAt: Date;
  updatedAt?: Date;
}

class MongoBaseService<T extends BaseModel> {
  protected baseUrl: string;
  protected entityName: string;

  constructor(entityName: string) {
    const envBaseUrl = process.env.REACT_APP_API_BASE_URL;
    if (!envBaseUrl) {
      throw new Error("REACT_APP_API_BASE_URL environment variable is not set");
    }
    this.baseUrl = envBaseUrl;
    this.entityName = entityName;
  }

  async fetchAll(): Promise<T[]> {
    try {
      const response = await axios.get<T[]>(`${this.baseUrl}/${this.entityName}`);
      return response.data;
    } catch (error) {
      console.error(`Failed to fetch ${this.entityName}:`, error);
      throw error;
    }
  }

  async fetchByDate(fetchDate: Date): Promise<T[]> {
    try {
      const no_of_days = parseInt(process.env.REACT_APP_LESSON_FETCH_DAYS || '90', 10); // Get number of days, default = 90
      const startDate = new Date(fetchDate.getTime() - no_of_days * 24 * 60 * 60 * 1000); // number of days before current date
      const endDate = new Date(fetchDate.getTime() + no_of_days * 24 * 60 * 60 * 1000); // number of days after current date
      const params = new URLSearchParams();
      params.append("startDate", startDate.toISOString().split('T')[0]);
      params.append("endDate", endDate.toISOString().split('T')[0]);
      const url = `${this.baseUrl}/${this.entityName}?${params.toString()}`;
      const response = await axios.get<T[]>(url);
      return response.data;
    } catch (error) {
      console.error(`Failed to fetch ${this.entityName} by date range:`, error);
      throw error;
    }
  }

  async add(item: T): Promise<T> {
    try {
      const response = await axios.post<T>(`${this.baseUrl}/${this.entityName}`, item);
      return response.data;
    } catch (error) {
      console.error(`Failed to add ${this.entityName}:`, error);
      throw error;
    }
  }

  async update(item: T): Promise<T> {
    try {
      const response = await axios.put<T>(`${this.baseUrl}/${this.entityName}/${item._id}`, item);
      return response.data;
    } catch (error) {
      console.error(`Failed to update ${this.entityName} with id ${item._id}:`, error);
      throw error;
    }
  }

  async remove(id: string): Promise<void> {
    try {
      const response = await axios.delete(`${this.baseUrl}/${this.entityName}/${id}`);
      return response.data;
    } catch (error) {
      console.error(`Failed to delete ${this.entityName} with id ${id}:`, error);
      throw error;
    }
  }

  async removeByStudentId(studentId: string): Promise<T[]> {
    try {
      const response = await axios.delete<T[]>(`${this.baseUrl}/${this.entityName}/byStudent/${studentId}`);
      console.log(response.data);
      return response.data;
    } catch (error) {
      console.error(`Failed to fetch and delete ${this.entityName} by studentId ${studentId}:`, error);
      throw error;
    }
  }
}


class FirestoreBaseService<T extends BaseModel> {
  protected collectionName: string;

  constructor(collectionName: string) {
    this.collectionName = collectionName;
  }

  async fetchAll(): Promise<T[]> {
    try {
      const db = authService.getFirestoreDb();
      const querySnapshot = await getDocs(collection(db, this.collectionName));
      const items: T[] = [];

      querySnapshot.forEach((doc) => {
        const data = doc.data();
        items.push({
          _id: doc.id,
          ...data,
          createdAt: data.createdAt?.toDate() || new Date(),
          updatedAt: data.updatedAt?.toDate() || new Date(),
        } as T);
      });

      return items;
    } catch (error) {
      console.error(`Failed to fetch ${this.collectionName}:`, error);
      throw error;
    }
  }

  async fetchByDate(fetchDate: Date): Promise<T[]> {
    try {
      const db = authService.getFirestoreDb();
      const no_of_days = parseInt(process.env.REACT_APP_LESSON_FETCH_DAYS || '90', 10);
      const startDate = new Date(fetchDate.getTime() - no_of_days * 24 * 60 * 60 * 1000);
      const endDate = new Date(fetchDate.getTime() + no_of_days * 24 * 60 * 60 * 1000);

      const startTimestamp = Timestamp.fromDate(startDate);
      const endTimestamp = Timestamp.fromDate(endDate);

      const q = query(
        collection(db, this.collectionName),
        where('createdAt', '>=', startTimestamp),
        where('createdAt', '<=', endTimestamp),
        orderBy('createdAt', 'desc')
      );

      const querySnapshot = await getDocs(q);
      const items: T[] = [];

      querySnapshot.forEach((doc) => {
        const data = doc.data();
        items.push({
          _id: doc.id,
          ...data,
          createdAt: data.createdAt?.toDate() || new Date(),
          updatedAt: data.updatedAt?.toDate() || new Date(),
        } as T);
      });

      return items;
    } catch (error) {
      console.error(`Failed to fetch ${this.collectionName} by date range:`, error);
      throw error;
    }
  }

  async add(item: T): Promise<T> {
    try {
      const db = authService.getFirestoreDb();
      const now = new Date();
      const { _id, ...itemWithoutId } = item;

      // Create document data with proper typing for Firestore
      const docData = Object.assign({}, itemWithoutId, {
        createdAt: Timestamp.fromDate(now),
        updatedAt: Timestamp.fromDate(now),
      });

      const docRef = await addDoc(collection(db, this.collectionName), docData as any);

      return {
        ...item,
        _id: docRef.id,
        createdAt: now,
        updatedAt: now,
      };
    } catch (error) {
      console.error(`Failed to add ${this.collectionName}:`, error);
      throw error;
    }
  }

  async update(item: T): Promise<T> {
    try {
      if (!item._id) {
        throw new Error("Item _id is required for update operation");
      }

      const now = new Date();
      const { _id, ...itemWithoutId } = item;

      const docData = {
        ...itemWithoutId,
        updatedAt: Timestamp.fromDate(now),
      };

      const db = authService.getFirestoreDb();
      const docRef = doc(db, this.collectionName, item._id);
      await updateDoc(docRef, docData);

      return {
        ...item,
        updatedAt: now,
      };
    } catch (error) {
      console.error(`Failed to update ${this.collectionName} with id ${item._id}:`, error);
      throw error;
    }
  }

  async remove(id: string): Promise<void> {
    try {
      const db = authService.getFirestoreDb();
      const docRef = doc(db, this.collectionName, id);
      await deleteDoc(docRef);
    } catch (error) {
      console.error(`Failed to delete ${this.collectionName} with id ${id}:`, error);
      throw error;
    }
  }

  async removeByStudentId(studentId: string): Promise<T[]> {
    try {
      const db = authService.getFirestoreDb();
      const q = query(
        collection(db, this.collectionName),
        where('studentId', '==', studentId)
      );

      const querySnapshot = await getDocs(q);
      const items: T[] = [];

      const batchDeletes: Promise<void>[] = [];

      querySnapshot.forEach((docItem) => {
        const data = docItem.data();
        items.push({
          _id: docItem.id,
          ...data,
          createdAt: data.createdAt?.toDate() || new Date(),
          updatedAt: data.updatedAt?.toDate() || new Date(),
        } as T);

        // Prepare delete operation
        const docRef = doc(db, this.collectionName, docItem.id);
        batchDeletes.push(deleteDoc(docRef));
      });

      // Execute all delete operations
      await Promise.all(batchDeletes);

      return items;
    } catch (error) {
      console.error(`Failed to fetch and delete ${this.collectionName} by studentId ${studentId}:`, error);
      throw error;
    }
  }
}

export class BaseService<T extends BaseModel> {
  protected service: MongoBaseService<T> | FirestoreBaseService<T>;

  constructor(entityName: string) {
    const IS_PROD = (authService as any).IS_PROD;
    if (IS_PROD) {
      this.service = new FirestoreBaseService<T>(entityName);
    } else {
      this.service = new MongoBaseService<T>(entityName);
    }
  }

  async fetchAll(): Promise<T[]> {
    return this.service.fetchAll();
  }

  async fetchByDate(fetchDate: Date): Promise<T[]> {
    return this.service.fetchByDate(fetchDate);
  }

  async add(item: T): Promise<T> {
    return this.service.add(item);
  }

  async update(item: T): Promise<T> {
    return this.service.update(item);
  }

  async remove(id: string): Promise<void> {
    return this.service.remove(id);
  }

  async removeByStudentId(studentId: string): Promise<T[]> {
    return this.service.removeByStudentId(studentId);
  }

}

