import React, { useState, useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import { Calendar, momentLocalizer, View } from "react-big-calendar";
import withDragAndDrop, {
  EventInteractionArgs,
} from "react-big-calendar/lib/addons/dragAndDrop";
import moment from "moment";
import "react-big-calendar/lib/css/react-big-calendar.css";
import "react-big-calendar/lib/addons/dragAndDrop/styles.css";

import { RootState, AppDispatch } from "../../store/store";
import { lessonInstanceActions } from "../../store/lessonSlice";
import { lessonRecurringActions } from "../../store/lessonSlice";
import { studentActions } from "../../store/studentSlice";
import { generateCalendarEvents, CalendarEvent } from "./utils/generateCalendarEvents";
import { handleEventReschedule } from "./utils/handleEventReschedule";
import { handleLessonRecurringDelete } from "./utils/handleLessonDelete";
import { updateLessonStatus } from "./utils/updateLessonStatus";
import ViewEventModal from "./modals/ViewEventModal";
import EditEventModal from "./modals/EditEventModal";
import AddLessonModal from "./modals/AddLessonModal";
import { useModals } from "./hooks/useModals";
import SignatureModal from "./modals/SignatureModal";
import CompleteLessonModal from "./modals/CompleteLessonModal";
import { LessonInstance } from "../../models/LessonInstance";
import { eventColors } from "../Utils/Styled";

const localizer = momentLocalizer(moment);
const DnDCalendar = withDragAndDrop<CalendarEvent, object>(Calendar);

const EventComponent: React.FC<{ event: CalendarEvent }> = ({ event }) => {
  const startTime = moment(event.start).format('HH:mm');
  const endTime = moment(event.end).format('HH:mm');
  let title = event.title;
  if (event.resource?.type === 'rescheduled') {
    title += ' (Make-up)';
  }

  return (
    <div style={{ padding: '2px' }}>
      <div style={{ fontWeight: 'bold' }}>{title}</div>
      <div style={{ fontSize: '0.8em', color: '#fff' }}>{startTime} - {endTime}</div>
    </div>
  );
};

const TeachingSchedule: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [view, setView] = useState<View>("month");
  const [currentDate, setCurrentDate] = useState(new Date());

  // Get lesson data from Redux store
  const lessonInstances = useSelector((state: RootState) => state.lessonsInstances.items || []);
  const lessonRecurrings = useSelector((state: RootState) => state.lessonRecurrings.items || []);
  const students = useSelector((state: RootState) => state.students.items || []);
  const lessonInstancesLoading = useSelector((state: RootState) => state.lessonsInstances.loading);
  const lessonRecurringsLoading = useSelector((state: RootState) => state.lessonRecurrings.loading);

  // Selected event for editing or null if modal closed
  const [selectedEvent, setSelectedEvent] = useState<CalendarEvent | null>(null);

  function getDateRange(): { start: Date; end: Date } {
    const no_of_days = parseInt(process.env.REACT_APP_LESSON_FETCH_DAYS || '90', 10); // Get number of days, default = 90
    const start = new Date(currentDate.getTime() - no_of_days * 24 * 60 * 60 * 1000); // number of days before current date
    const end = new Date(currentDate.getTime() + no_of_days * 24 * 60 * 60 * 1000); // number of days after current date
    return { start, end };
  }

  function getDateRangeStr(): { startStr: string; endStr: string } {
    const { start, end } = getDateRange();
    const startStr = start.toISOString().split('T')[0]; // Format as YYYY-MM-DD
    const endStr = end.toISOString().split('T')[0]; // Format as YYYY-MM-DD
    return { startStr, endStr };
  }

  const {
    modalState,
    signatureSigner,
    setSignatureSigner,
    teacherSignature,
    studentSignature,
    feePaid,
    setFeePaid,
    setSignature,
    openAddLessonModal,
    closeAddLessonModal,
    openViewEventModal,
    closeViewEventModal,
    openEditEventModal,
    closeEditEventModal,
    openSignatureModal,
    closeSignatureModal,
    openCompleteLessonModal,
    closeCompleteLessonModal,
    closeAllModals,
  } = useModals();

  // State for pre-filling AddLessonModal from calendar clicks
  const [AddLessonModalPrefillDate, setAddLessonModalPrefillDate] = useState<string>("");

  // Use a ref to track if an update is currently in progress
  const isUpdatingRef = React.useRef(false);


  // Load lesson data and generate calendar events
  useEffect(() => {
    // Fetch lesson data
    dispatch(lessonInstanceActions.fetchByDate({ fetchDate: currentDate }) as any);
    dispatch(lessonRecurringActions.fetchAll() as any);
    dispatch(studentActions.fetchAll() as any);
  }, [dispatch, currentDate]);

  // Generate calendar events from lesson data
  useEffect(() => {
    if (lessonInstances.length > 0 || lessonRecurrings.length > 0) {
      const {startStr: fromDate, endStr: toDate} = getDateRangeStr();

      const allEvents = generateCalendarEvents(
        lessonInstances,
        lessonRecurrings,
        students,
        fromDate,
        toDate
      );

      // Add status to events for color coding
      const eventsWithStatus = allEvents.map(event => ({
        ...event,
        status: event.resource?.status || "scheduled"
      }));

      setEvents(eventsWithStatus);
    }
  }, [lessonInstances, lessonRecurrings, students, currentDate]);

  // Periodic lesson status update
  useEffect(() => {
    const updateIntervalMinutes = parseInt(process.env.REACT_APP_LESSON_STATUS_UPDATE_INTERVAL || '5', 10);
    const updateIntervalMs = updateIntervalMinutes * 60 * 1000;

    const performStatusUpdate = async () => {
      // Wait for lessonInstances and lessonRecurrings to finish loading
      if (lessonInstancesLoading || lessonRecurringsLoading) {
        return;
      }
      
      // If an update is already in progress, skip this execution
      if (isUpdatingRef.current) {
        return;
      }

      isUpdatingRef.current = true;
      
      try {
        const {startStr: fromDate, endStr: toDate} = getDateRangeStr();

        const { updatedInstances, newInstances } = updateLessonStatus(
          lessonInstances,
          lessonRecurrings,
          students,
          fromDate,
          toDate
        );

        // Dispatch updates for existing instances
        if (updatedInstances.length > 0) {
          for (const instance of updatedInstances) {
            await dispatch(lessonInstanceActions.update(instance) as any);
          }
        }

        // Dispatch creates for new instances
        if (newInstances.length > 0) {
          for (const instance of newInstances) {
            await dispatch(lessonInstanceActions.add(instance) as any);
          }
        }

      } catch (error) {
        console.error('Error updating lesson statuses:', error);
      } finally {
        // Reset the updating flag when done
        isUpdatingRef.current = false;
      }
    };

    // Perform initial update
    performStatusUpdate();

    // Set up periodic updates
    const intervalId = setInterval(performStatusUpdate, updateIntervalMs);

    // Cleanup function
    return () => {
      clearInterval(intervalId);
    };
  }, [dispatch, lessonInstances, lessonRecurrings, currentDate, students]);

  // Handle escape key press to close all modals
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        closeAllModals();
      }
    };

    // Add event listener when component mounts
    document.addEventListener('keydown', handleKeyDown);

    // Remove event listener when component unmounts
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [closeAllModals]);

  // Update event on drag/drop
  const onEventDrop = async (args: EventInteractionArgs<CalendarEvent>) => {
    await handleEventReschedule(args, dispatch, lessonRecurrings, students);
  };

  const handleViewChange = (newView: View) => {
    setView(newView);
  };

  // Function to determine event style based on status
  const eventStyleGetter = (event: CalendarEvent) => {
    const colors = eventColors[event.status as keyof typeof eventColors] || eventColors.scheduled;
    const backgroundColor = colors.background;
    const borderColor = colors.border;

    return {
      style: {
        backgroundColor,
        borderColor,
        color: 'white',
        borderRadius: '3px',
        opacity: 0.8,
      }
    };
  };

  // When user clicks on event, open modal and fill form with event data
  const handleSelectEvent = (event: CalendarEvent) => {
    setSelectedEvent(event);
    openViewEventModal();
  };

  // Handle save changes from modal
  const handleSaveChanges = async (updatedEvent: {
    event: CalendarEvent;
    newStart: Date;
    newEnd: Date;
  }) => {
    if (!updatedEvent.event) return;

    // Create the event interaction args for handleEventReschedule
    const rescheduleArgs = {
      event: updatedEvent.event,
      start: updatedEvent.newStart,
      end: updatedEvent.newEnd,
    };

    // Use handleEventReschedule to properly reschedule the lesson
    await handleEventReschedule(rescheduleArgs, dispatch, lessonRecurrings, students);

    setSelectedEvent(null);
  };

  // Handle lesson deletion
  const handleDelete = async () => {
    if (!selectedEvent) return;
    if (window.confirm("Are you sure you want to delete this lesson?")) {
      var lessonToDelete = selectedEvent.resource as LessonInstance;
      lessonToDelete = {... lessonToDelete}; // Create a shallow copy to avoid direct state mutation

      if (!lessonToDelete) {
        console.error("No lesson data found for deletion.");
        return;
      }

      // Delete if event is a unacknowledged lesson instance
      if (lessonToDelete.status === "unacknowledged") {
        lessonToDelete.type = 'cancelled';
        lessonToDelete.actualFee = 0;
        await dispatch(lessonInstanceActions.update(lessonToDelete));
      }
      // Delete if event is a recurring lesson
      else if (lessonToDelete.lessonRecurringId && !lessonToDelete._id) {
        const recurringLessonToDelete = handleLessonRecurringDelete(lessonToDelete, students);
        await dispatch(lessonInstanceActions.add(recurringLessonToDelete));
      }
      // Delete if event is an existing lesson instance
      else if (lessonToDelete._id) {
        await dispatch(lessonInstanceActions.remove(lessonToDelete._id));
      }
      setSelectedEvent(null);
    }
  };

  return (
    <>
      <div style={{ height: "70vh" }}>
        <DnDCalendar
          localizer={localizer}
          events={events}
          startAccessor="start"
          endAccessor="end"
          style={{ height: "100%" }}
          onEventDrop={onEventDrop}
          resizable
          draggableAccessor={() => true}
          view={view}
          date={currentDate}
          onNavigate={(date) => setCurrentDate(date)}
          onView={handleViewChange}
          onSelectEvent={handleSelectEvent}
          onSelectSlot={(slotInfo) => {
            const date = slotInfo.start;
            const dateStr = date.toLocaleDateString('en-CA'); // Format as YYYY-MM-DD
            setAddLessonModalPrefillDate(dateStr);
            openAddLessonModal();
          }}
          selectable
          eventPropGetter={eventStyleGetter}
          components={{
            event: EventComponent
          }}
        />
      </div>

      <ViewEventModal
        isOpen={modalState.viewEventModal}
        selectedEvent={selectedEvent}
        onDelete={handleDelete}
        onClose={closeViewEventModal}
        onEdit={() => {
          openEditEventModal();
          closeViewEventModal();
        }}
        openCompleteLessonModal={(expectedFee: number) => openCompleteLessonModal(expectedFee)}
      />
      <CompleteLessonModal
        isOpen={modalState.completeLessonModal}
        selectedEvent={selectedEvent}
        setSignatureSigner={setSignatureSigner}
        openSignatureModal={openSignatureModal}
        teacherSignature={teacherSignature}
        studentSignature={studentSignature}
        feePaid={feePaid}
        setFeePaid={setFeePaid}
        onSubmit={() => {
          if (!selectedEvent) return;
          let updatedLessonInstance: LessonInstance = { ...selectedEvent.resource } as LessonInstance;
          if (teacherSignature) {
            updatedLessonInstance.teacherSignature = {
              signedAt: new Date().toISOString(),
              imageUrl: teacherSignature,
            };
          }
          if (studentSignature) {
            updatedLessonInstance.studentSignature = {
              signedAt: new Date().toISOString(),
              imageUrl: studentSignature,
            };
          }
          updatedLessonInstance.actualFee = parseFloat(feePaid);
          if (teacherSignature && studentSignature) {
            updatedLessonInstance.status = "completed";
          }
          const updatedEvent = {
            ...selectedEvent,
            resource: updatedLessonInstance,
            status: updatedLessonInstance.status
          };
          setSelectedEvent(updatedEvent);
          dispatch(lessonInstanceActions.update(updatedLessonInstance));
          dispatch(lessonInstanceActions.fetchByDate({ fetchDate: currentDate }) as any);
          closeCompleteLessonModal();
        }}
        onClose={closeCompleteLessonModal}
      />

      <EditEventModal
        isOpen={modalState.editEventModal}
        selectedEvent={selectedEvent}
        onSave={handleSaveChanges}
        onClose={() => {
          closeEditEventModal();
          openViewEventModal();
        }}
      />

      <AddLessonModal
        isOpen={modalState.addLessonModal}
        onClose={closeAddLessonModal}
        prefillDate={AddLessonModalPrefillDate}
      />

      <SignatureModal
        isOpen={modalState.signatureModal}
        onClose={closeSignatureModal}
        onSignatureSubmit={(signature: string) => {
          closeSignatureModal();
          setSignature(signatureSigner as "teacher" | "student", signature);
        }}
      />
    </>
  );
};

export default TeachingSchedule;
