import React from "react";
import { Student } from "../../models/Student";
import StudentDetails from "./StudentDetails";
import { LessonRecurring } from "../../models/LessonRecurring";

type Props = {
  students: Student[];
  lessonRecurring: LessonRecurring[];
  loading: boolean;
  onEdit: (student: Student) => void;
  onDelete: (student: Student) => void;
  onAddLessonRecurring: (student: Student) => void;
  onEditLessonRecurring: (lesson: LessonRecurring) => void;
  onDeleteLessonRecurring: (lesson: LessonRecurring) => void;
};

const StudentList: React.FC<Props> = ({ students, lessonRecurring, loading, onEdit, onDelete, onAddLessonRecurring, onEditLessonRecurring, onDeleteLessonRecurring }) => {
  if (loading) {
    return <p>Loading students...</p>;
  }

  if (!loading && students.length === 0) {
    return <p style={{ color: "#718096" }}>No students yet.</p>;
  }

  return (
    <>
      {students.map((student) => (
        <StudentDetails
          key={student._id || student.name}
          student={student}
          onEdit={onEdit}
          onDelete={onDelete}
          onAddLessonRecurring={onAddLessonRecurring}
          onEditLessonRecurring={onEditLessonRecurring}
          onDeleteLessonRecurring={onDeleteLessonRecurring}
          studentLessonRecurring={lessonRecurring.filter((lr) => lr.studentId === student._id)}
        />
      ))}
    </>
  );
};

export default StudentList;
