import React from "react";
import { Student } from "../../models/Student";
import { LessonRecurring } from "../../models/LessonRecurring";
import { Card, CardTitle, Info, Button } from "../Utils/Styled";

type Props = {
  student: Student;
  studentLessonRecurring: LessonRecurring[];
  onEdit: (student: Student) => void;
  onDelete: (student: Student) => void;
  onAddLessonRecurring: (student: Student) => void;
  onEditLessonRecurring: (lesson: LessonRecurring) => void;
  onDeleteLessonRecurring: (lesson: LessonRecurring) => void;
};

const StudentDetails: React.FC<Props> = ({ student, studentLessonRecurring, onEdit, onDelete, onAddLessonRecurring, onEditLessonRecurring, onDeleteLessonRecurring }) => {
  
  return (
    <Card>
      <CardTitle>Student Details</CardTitle>
      <Info><span>Name:</span> {student.name}</Info>
      <Info><span>Email:</span> {student.email || "N/A"}</Info>
      <Info><span>Phone:</span> {student.phone || "N/A"}</Info>
      <Info><span>Date of Birth:</span> {student.dateOfBirth || "N/A"}</Info>
      <Info><span>Notes:</span> {student.notes || "N/A"}</Info>
      <Info><span>Fee:</span> {student.fee ? `$${student.fee}` : "N/A"}</Info>
      <Info><span>Created At:</span> {student.createdAt.toString()}</Info>
      <Info><span>Updated At:</span> {student.updatedAt.toString()}</Info>

      {/* Recurring Lessons Section */}
      <div style={{ marginTop: 20 }}>
        <CardTitle>Recurring Lessons</CardTitle>
        {studentLessonRecurring.length > 0 ? (
          <div>
            {studentLessonRecurring.map((lesson: LessonRecurring) => (
              <div key={lesson._id} style={{ 
                border: '1px solid #e2e8f0', 
                borderRadius: '8px', 
                padding: '12px', 
                marginBottom: '8px',
                backgroundColor: '#f7fafc',
                position: 'relative'
              }}>
                <Info><span>Day:</span> {lesson.dayOfWeek}</Info>
                <Info><span>Time:</span> {lesson.startTime} - {lesson.endTime}</Info>
                <Info><span>Start Date:</span> {new Date(lesson.startDate).toLocaleDateString()}</Info>
                {lesson.endDate && (
                  <Info><span>End Date:</span> {new Date(lesson.endDate).toLocaleDateString()}</Info>
                )}
                {lesson.notes && <Info><span>Notes:</span> {lesson.notes}</Info>}
                <Button
                  variant="primary"
                  style={{ position: 'absolute', top: 8, right: 8, padding: '4px 8px', fontSize: '0.8rem' }}
                  onClick={() => onEditLessonRecurring(lesson)}
                >
                  Edit
                </Button>
                <Button
                  variant="danger"
                  style={{ position: 'absolute', top: 8, right: 60, padding: '4px 8px', fontSize: '0.8rem' }}
                  onClick={() => onDeleteLessonRecurring(lesson)}
                >
                  Remove
                </Button>
              </div>
            ))}
          </div>
        ) : (
          <Info>No recurring lessons scheduled</Info>
        )}
      </div>

      <div style={{ marginTop: 14 }}>
        <Button onClick={() => onEdit(student)}>Edit</Button>
        <Button variant="danger" onClick={() => onDelete(student)}>Remove</Button>
        <Button variant="primary" onClick={() => onAddLessonRecurring(student)} style={{ marginLeft: 8 }}>Add Weekly Lesson</Button>
      </div>
    </Card>
  );
};

export default StudentDetails;
