import { LessonInstance } from "../../../models/LessonInstance";
import { CalendarEvent } from "./generateCalendarEvents";
import { Student } from "../../../models/Student";

export function handleLessonRecurringDelete (
  lessonToDelete: LessonInstance,
  students: Student[],
  cancelledReason?: string,
  cancelledBy?: "teacher" | "student"
): LessonInstance {
  const student = students.find(s => s._id === lessonToDelete.studentId);

  const cancelledLessonInstance: LessonInstance = {
    _id: '',
    studentId: lessonToDelete.studentId,
    lessonRecurringId: lessonToDelete.lessonRecurringId,
    date: lessonToDelete.date,
    startTime: lessonToDelete.startTime,
    endTime: lessonToDelete.endTime,
    type: 'cancelled',
    status: 'scheduled',
    expectedFee: student?.fee || 0,
    actualFee: 0,
    cancelledReason: cancelledReason || 'Lesson cancelled',
    ...(cancelledBy && { cancelledBy }),
    createdAt: new Date(),
    updatedAt: new Date(),
  };
  return cancelledLessonInstance;
};