import React from "react";
import { Form, Label, Input, Textarea, Button } from "../../../Utils/Styled";

type Props = {
  form: any;
  loading: boolean;
  modalMode: "add" | "edit";
  onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => void;
  onSubmit: (e: React.FormEvent) => void;
  onCancel: () => void;
};

const LessonRecurringForm: React.FC<Props> = ({
  form,
  loading,
  modalMode,
  onChange,
  onSubmit,
  onCancel,
}) => (
  <Form onSubmit={onSubmit}>
    <Label>
      Start Date:
      <Input name="startDate" value={form.startDate} onChange={onChange} type="date" required />
    </Label>
    
    <Label>
      End Date (optional):
      <Input name="endDate" value={form.endDate} onChange={onChange} type="date" />
    </Label>
    
    <Label>
      Day of Week:
      <select name="dayOfWeek" value={form.dayOfWeek || ''} onChange={onChange} required>
        <option value="">Select a day</option>
        <option value="Sunday">Sunday</option>
        <option value="Monday">Monday</option>
        <option value="Tuesday">Tuesday</option>
        <option value="Wednesday">Wednesday</option>
        <option value="Thursday">Thursday</option>
        <option value="Friday">Friday</option>
        <option value="Saturday">Saturday</option>
      </select>
    </Label>
    
    <Label>
      Start Time:
      <Input name="startTime" value={form.startTime} onChange={onChange} type="time" required />
    </Label>
    
    <Label>
      End Time:
      <Input name="endTime" value={form.endTime} onChange={onChange} type="time" required />
    </Label>
    
    <Label>
      Notes:
      <Textarea name="notes" value={form.notes} onChange={onChange} />
    </Label>
    
    <div>
      <Button type="submit" disabled={loading}>
        {modalMode === "add" ? "Add Weekly Lesson" : "Save Changes"}
      </Button>
      <Button
        type="button"
        variant="secondary"
        onClick={onCancel}
      >
        Cancel
      </Button>
    </div>
  </Form>
);

export default LessonRecurringForm;
