import React, { useState } from "react";
import { authService, LoginRequest } from "../../services/authService";
import { useNavigate } from "react-router-dom";
import { useAuth } from "./AuthContext";
import { Button, TextField, Typography, Box, Alert } from "@mui/material";
import { GoogleSignInButton, GoogleLogoSvg } from "../Utils/Styled";

const Login: React.FC = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();
  const { login } = useAuth();
  const IS_PROD = (authService as any).IS_PROD;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    try {
      const credentials: LoginRequest = { email, password };
      const response = await authService.login(credentials);
      login(response.user);
      navigate("/calendar");
    } catch (err) {
      setError("Login failed. Please check your email and password.");
    }
  };

  // TODO: Enable Google Sign-In when backend is set up to handle it
  // const handleGoogleSignIn = async () => {
  //   setError(null);
  //   try {
  //     await authService.signInWithGoogle();
  //     // Note: Navigation will happen after redirect via AuthContext
  //   } catch (err: any) {
  //     setError("Google sign-in failed. Please try again.");
  //   }
  // };

  return (
    <Box maxWidth={400} mx="auto" mt={5}>
      <Typography variant="h5" component="h1" gutterBottom>
        Login
      </Typography>
      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      <form onSubmit={handleSubmit}>
        <TextField
          label="Email"
          type="email"
          fullWidth
          margin="normal"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />
        <TextField
          label="Password"
          type="password"
          fullWidth
          margin="normal"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
        
        {IS_PROD ?
          <GoogleSignInButton
            // TODO: Disable type="submit" and enable onClick when backend is set up
            type="submit"
            // onClick={handleGoogleSignIn}
          >
            <GoogleLogoSvg />
            Sign in with Google
          </GoogleSignInButton>
          :
          <Button type="submit" variant="contained" color="primary" fullWidth sx={{ mt: 2 }}>
            Login
          </Button>
        }
        

        
      </form>
    </Box>
  );
};

export default Login;
