// createEntitySlice.ts
import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import { castDraft } from 'immer';

interface EntityState<T> {
  items: T[];
  loading: boolean;
  error?: string;
}

interface EntityService<T> {
  fetchAll(): Promise<T[]>;
  fetchByDate?(fetchDate: Date): Promise<T[]>;
  add(item: T): Promise<T>;
  update(item: T): Promise<T>;
  remove(id: string): Promise<void>;
  removeByStudentId(studentId: string): Promise<T[]>;
}

export function createEntitySlice<T extends { _id?: string }>(
  name: string,
  service: EntityService<T>
) {
  const fetchAll = createAsyncThunk(`${name}/fetchAll`, async () => {
    return await service.fetchAll();
  });

  const fetchByDate = createAsyncThunk(`${name}/fetchByDate`, async ({ fetchDate }: { fetchDate: Date; }) => {
    if (!service.fetchByDate) {
      throw new Error('fetchByDate not implemented');
    }
    return await service.fetchByDate(fetchDate);
  });

  const add = createAsyncThunk(`${name}/add`, async (item: T) => {
    return await service.add(item);
  });

  const update = createAsyncThunk(`${name}/update`, async (item: T) => {
    return await service.update(item);
  });

  const remove = createAsyncThunk(`${name}/remove`, async (id: string) => {
    await service.remove(id);
    return id;
  });

  const removeByStudentId = createAsyncThunk(`${name}/removeByStudentId`, async (studentId: string) => {
    await service.removeByStudentId(studentId);
    return studentId;
  });

  const initialState: EntityState<T> = {
    items: [],
    loading: false,
    error: undefined,
  };

  const slice = createSlice({
    name,
    initialState,
    reducers: {},
    extraReducers: (builder) => {
      builder
        .addCase(fetchAll.pending, (state) => {
          state.loading = true;
          state.error = undefined;
        })
        .addCase(fetchAll.fulfilled, (state, action: PayloadAction<T[]>) => {
          state.items = castDraft(action.payload);
          state.loading = false;
        })
        .addCase(fetchAll.rejected, (state, action) => {
          state.loading = false;
          state.error = action.error.message;
        })
        .addCase(fetchByDate.pending, (state) => {
          state.loading = true;
          state.error = undefined;
        })
        .addCase(fetchByDate.fulfilled, (state, action: PayloadAction<T[]>) => {
          const newItems = action.payload.filter(newItem => !state.items.some(existing => existing._id === newItem._id));
          state.items.push(...castDraft(newItems));
          state.loading = false;
        })
        .addCase(fetchByDate.rejected, (state, action) => {
          state.loading = false;
          state.error = action.error.message;
        })
        .addCase(add.pending, (state) => {
          state.loading = true;
          state.error = undefined;
        })
        .addCase(add.fulfilled, (state, action: PayloadAction<T>) => {
          state.items.push(castDraft(action.payload));
          state.loading = false;
        })
        .addCase(add.rejected, (state, action) => {
          state.loading = false;
          state.error = action.error.message;
        })
        .addCase(update.pending, (state) => {
          state.loading = true;
          state.error = undefined;
        })
        .addCase(update.fulfilled, (state, action: PayloadAction<T>) => {
          const idx = state.items.findIndex(item => item._id === action.payload._id);
          if (idx !== -1) {
            state.items[idx] = castDraft(action.payload);
          }
          state.loading = false;
        })
        .addCase(update.rejected, (state, action) => {
          state.loading = false;
          state.error = action.error.message;
        })
        .addCase(remove.pending, (state) => {
          state.loading = true;
          state.error = undefined;
        })
        .addCase(remove.fulfilled, (state, action: PayloadAction<string>) => {
          state.items = state.items.filter(item => item._id !== action.payload);
          state.loading = false;
        })
        .addCase(remove.rejected, (state, action) => {
          state.loading = false;
          state.error = action.error.message;
        })
        .addCase(removeByStudentId.pending, (state) => {
          state.loading = true;
          state.error = undefined;
        })
        .addCase(removeByStudentId.fulfilled, (state, action: PayloadAction<string>) => {
          state.items = state.items.filter(item => item._id !== action.payload);
          state.loading = false;
        })
        .addCase(removeByStudentId.rejected, (state, action) => {
          state.loading = false;
          state.error = action.error.message;
        });
    },
  });

  return {
    reducer: slice.reducer,
    actions: { fetchAll, fetchByDate, add, update, remove, removeByStudentId },
  };
}
