import React, { FormEvent, useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { RootState, AppDispatch } from "../../../store/store";
import { lessonInstanceActions } from "../../../store/lessonSlice";
import { LessonInstance } from "../../../models/LessonInstance";
import { ModalOverlayBlur, ModalContent, Title, Form, Label, Input, Button, ModalActions } from "../../Utils/Styled";

interface AddLessonModalProps {
  isOpen: boolean;
  onClose: () => void;
  prefillDate?: string;
  prefillStartTime?: string;
  prefillEndTime?: string;
}

const AddLessonModal: React.FC<AddLessonModalProps> = ({ 
  isOpen, 
  onClose, 
  prefillDate = "", 
  prefillStartTime = "", 
  prefillEndTime = "" 
}) => {
  const dispatch = useDispatch<AppDispatch>();
  const students = useSelector((state: RootState) => state.students.items || []);

  const [newLessonStudent, setNewLessonStudent] = useState("");
  const [newLessonDate, setNewLessonDate] = useState(prefillDate);
  const [newLessonStart, setNewLessonStart] = useState(prefillStartTime);
  const [newLessonEnd, setNewLessonEnd] = useState(prefillEndTime);

  // Reset form when modal closes or prefill props change
  useEffect(() => {
    if (!isOpen) {
      setNewLessonStudent("");
      setNewLessonDate("");
      setNewLessonStart("");
      setNewLessonEnd("");
    } else {
      setNewLessonDate(prefillDate);
      setNewLessonStart(prefillStartTime);
      setNewLessonEnd(prefillEndTime);
    }
  }, [isOpen, prefillDate, prefillStartTime, prefillEndTime]);

  const parseDatetimeLocalInput = (value: string) => {
    return new Date(value);
  };

  const handleAddLesson = async (e: FormEvent) => {
    e.preventDefault();

    if (!newLessonStudent || !newLessonDate || !newLessonStart || !newLessonEnd) {
      alert("Please fill in all fields");
      return;
    }

    const startDateTime = parseDatetimeLocalInput(`${newLessonDate}T${newLessonStart}`);
    const endDateTime = parseDatetimeLocalInput(`${newLessonDate}T${newLessonEnd}`);

    if (endDateTime <= startDateTime) {
      alert("End time must be after start time");
      return;
    }

    try {
      const student = students.find(s => s._id === newLessonStudent);
      const newLesson: LessonInstance = {
        _id: "", // Will be generated by the backend
        studentId: newLessonStudent,
        lessonRecurringId: "", // Empty for ad-hoc lessons
        date: newLessonDate,
        startTime: newLessonStart,
        endTime: newLessonEnd,
        type: "regular" as const,
        status: "scheduled" as const,
        expectedFee: student?.fee || 0,
        actualFee: 0,
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      await dispatch(lessonInstanceActions.add(newLesson as any) as any);
      
      // Refresh the lesson data
      const fetchDate = new Date(newLessonDate);
      await dispatch(lessonInstanceActions.fetchByDate({ fetchDate }) as any);
      
      // Reset form and close modal
      setNewLessonStudent("");
      setNewLessonDate("");
      setNewLessonStart("");
      setNewLessonEnd("");
      onClose();
    } catch (error) {
      console.error("Error adding lesson:", error);
      alert("Error adding lesson. Please try again.");
    }
  };

  if (!isOpen) return null;

  return (
    <ModalOverlayBlur>
      <ModalContent>
        <h2>Add New Lesson</h2>
        <Form onSubmit={handleAddLesson}>
          <Label>
            Student:
            <Input
              as="select"
              value={newLessonStudent}
              onChange={(e) => setNewLessonStudent(e.target.value)}
              required
            >
              <option value="">Select a student</option>
              {students.map(student => (
                <option key={student._id} value={student._id}>{student.name}</option>
              ))}
            </Input>
          </Label>

          <Label>
            Date:
            <Input
              type="date"
              value={newLessonDate}
              onChange={(e) => setNewLessonDate(e.target.value)}
              required
            />
          </Label>

          <Label>
            Start Time:
            <Input
              type="time"
              value={newLessonStart}
              onChange={(e) => setNewLessonStart(e.target.value)}
              required
            />
          </Label>

          <Label>
            End Time:
            <Input
              type="time"
              value={newLessonEnd}
              onChange={(e) => setNewLessonEnd(e.target.value)}
              required
            />
          </Label>

          <ModalActions>
            <Button type="button" variant="secondary" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit">
              Add Lesson
            </Button>
          </ModalActions>
        </Form>
      </ModalContent>
    </ModalOverlayBlur>
  );
};

export default AddLessonModal;
