import { useState } from "react";
import { DayOfWeek } from "../../../models/LessonRecurring";

const getCurrentDate = (): string => {
  const now = new Date();
  const year = now.getFullYear();
  const month = (now.getMonth() + 1).toString().padStart(2, '0');
  const day = now.getDate().toString().padStart(2, '0');
  return `${year}-${month}-${day}`;
};

const initialFormState = {
  _id: "",
  studentId: "",
  startDate: getCurrentDate(),
  endDate: "",
  dayOfWeek: "" as DayOfWeek,
  startTime: "",
  endTime: "",
  notes: "",
};

export const useLessonRecurringForm = () => {
  const [lessonRecurringForm, setLessonRecurringForm] = useState(initialFormState);
  const [lessonRecurringEditId, setLessonRecurringEditId] = useState<string | undefined>(undefined);

  const resetLessonRecurringForm = () => {
    setLessonRecurringForm(initialFormState);
    setLessonRecurringEditId(undefined);
  };

  const setLessonRecurringStudentId = (id: string) => {
    setLessonRecurringForm({ ...lessonRecurringForm, studentId: id });
  };

  const handleLessonRecurringChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setLessonRecurringForm({ ...lessonRecurringForm, [e.target.name]: e.target.value });
  };

  return {
    lessonRecurringForm,
    lessonRecurringEditId,
    setLessonRecurringEditId,
    setLessonRecurringForm,
    resetLessonRecurringForm,
    handleLessonRecurringChange,
    setLessonRecurringStudentId
  };
};
