import { EventInteractionArgs } from "react-big-calendar/lib/addons/dragAndDrop";
import { LessonInstance } from "../../../models/LessonInstance";
import { LessonRecurring, DayOfWeek } from "../../../models/LessonRecurring";
import { AppDispatch } from "../../../store/store";
import { lessonInstanceActions } from "../../../store/lessonSlice";
import { CalendarEvent } from "./generateCalendarEvents";
import { Student } from "../../../models/Student";

// Helper function to check if a date matches the recurring lesson's day
const isOriginalRecurringDate = (
  lessonRecurringId: string,
  date: Date,
  startTime: string,
  endTime: string,
  lessonRecurrings: LessonRecurring[]
): boolean => {
  const recurring = lessonRecurrings.find(r => r._id === lessonRecurringId);
  if (!recurring) return false;

  const dayOfWeek = date.toLocaleDateString('en-US', { weekday: 'long' }) as DayOfWeek;
  const dateStr = date.toISOString().split('T')[0];

  // Check if the recurring lesson matches the date, time, and day of week
  if (recurring.dayOfWeek !== dayOfWeek) return false;
  if (recurring.startTime !== startTime) return false;
  if (recurring.endTime !== endTime) return false;

  // Check if it's within the recurring period
  if (dateStr < recurring.startDate) return false;
  if (recurring.endDate && dateStr > recurring.endDate) return false;

  return true;
};

// Handle drag and drop events
export const handleEventReschedule = async (
  { event, start, end }: EventInteractionArgs<CalendarEvent>,
  dispatch: AppDispatch,
  lessonRecurrings: LessonRecurring[],
  students: Student[]
) => {
  const newStartDate = new Date(start);
  const newEndDate = new Date(end);
  const newDateStr = newStartDate.toISOString().split('T')[0];
  const newDayOfWeek = newStartDate.toLocaleDateString('en-US', { weekday: 'long' }) as DayOfWeek;
  const newStartTime = newStartDate.toTimeString().split(' ')[0].substring(0, 5);
  const newEndTime = newEndDate.toTimeString().split(' ')[0].substring(0, 5);

  const eventToReschedule = event.resource as LessonInstance;

  if (!eventToReschedule) {
    console.error('No lesson instance data found');
    return;
  }

  const student = students.find(s => s._id === eventToReschedule.studentId);

  // Case 1: Event is from a recurring lesson (not yet a lesson instance)
  if (!eventToReschedule._id && eventToReschedule.lessonRecurringId) {
    // Get the original recurring lesson details
    const recurringLesson = lessonRecurrings.find(r => r._id === eventToReschedule.lessonRecurringId);

    if (recurringLesson?.dayOfWeek === newDayOfWeek &&
        recurringLesson?.startTime === newStartTime &&
        recurringLesson?.endTime === newEndTime) {
      // No changes, nothing to do
      return;
    }
    
    // Create new lesson instance for rescheduled lesson
    const newLessonInstance: LessonInstance = {
      _id: '',
      studentId: eventToReschedule.studentId,
      lessonRecurringId: eventToReschedule.lessonRecurringId,
      date: newDateStr,
      startTime: newStartTime,
      endTime: newEndTime,
      type: 'rescheduled',
      status: 'scheduled',
      expectedFee: student?.fee || 0,
      actualFee: 0,
      rescheduledFromDate: eventToReschedule.date,
      rescheduledFromStartTime: recurringLesson?.startTime,
      rescheduledFromEndTime: recurringLesson?.endTime,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    try {
      await dispatch(lessonInstanceActions.add(newLessonInstance));
      const fetchDate = new Date(newDateStr);
      await dispatch(lessonInstanceActions.fetchByDate({ fetchDate }));
    } catch (error) {
      console.error('Error creating lesson instance:', error);
    }
  }
  // Case 2: Event is already a lesson instance
  else if (eventToReschedule._id && eventToReschedule.status === 'scheduled') {
    // Check if rescheduling back to original recurring lesson position
    const isBackToOriginal = isOriginalRecurringDate(
      eventToReschedule.lessonRecurringId,
      newStartDate,
      newStartTime,
      newEndTime,
      lessonRecurrings
    );

    if (isBackToOriginal && eventToReschedule.type === 'rescheduled') {
      // Case 3: Delete the lesson instance as it's back to original recurring
      try {
        await dispatch(lessonInstanceActions.remove(eventToReschedule._id));
        const fetchDate = new Date(newDateStr);
        await dispatch(lessonInstanceActions.fetchByDate({ fetchDate }));
      } catch (error) {
        console.error('Error deleting lesson instance:', error);
      }
    } else {
      // Case 2: Update existing lesson instance
      const updatedLessonInstance: LessonInstance = {
        ...eventToReschedule,
        date: newDateStr,
        startTime: newStartTime,
        endTime: newEndTime,
        type: eventToReschedule.type === 'regular' ? 'rescheduled' : eventToReschedule.type,
        expectedFee: student?.fee || 0,
        updatedAt: new Date(),
      };

      try {
        await dispatch(lessonInstanceActions.update({
          ...eventToReschedule,
          ...updatedLessonInstance
        }));
        const fetchDate = new Date(newDateStr);
        await dispatch(lessonInstanceActions.fetchByDate({ fetchDate }));
      } catch (error) {
        console.error('Error updating lesson instance:', error);
      }
    }
  }
  // Case 3: Handle other statuses
  else {
    alert('Past lessons cannot be rescheduled');
  }
}
