import { useState } from 'react';
import { useCompleteLesson } from './useCompleteLesson';

interface ModalState {
  addLessonModal: boolean;
  viewEventModal: boolean;
  editEventModal: boolean;
  signatureModal: boolean;
  completeLessonModal: boolean;
}

export type SignerRole = null | "teacher" | "student";

export const useModals = () => {
  const [modalState, setModalState] = useState<ModalState>({
    addLessonModal: false,
    viewEventModal: false,
    editEventModal: false,
    signatureModal: false,
    completeLessonModal: false,
  });
  
  const [signatureSigner, setSignatureSigner] = useState<SignerRole>(null);

  const { teacherSignature, studentSignature, feePaid, setFeePaid, setSignature, resetSignatures } = useCompleteLesson();

  const openAddLessonModal = () => {
    setModalState(prev => ({ ...prev, addLessonModal: true }));
  };

  const closeAddLessonModal = () => {
    setModalState(prev => ({ ...prev, addLessonModal: false }));
  };

  const openViewEventModal = () => {
    setModalState(prev => ({ ...prev, viewEventModal: true }));
  };

  const closeViewEventModal = () => {
    setModalState(prev => ({ ...prev, viewEventModal: false }));
  };

  const openEditEventModal = () => {
    setModalState(prev => ({ ...prev, editEventModal: true }));
  };

  const closeEditEventModal = () => {
    setModalState(prev => ({ ...prev, editEventModal: false }));
  };

  const openSignatureModal = () => {
    setModalState(prev => ({ ...prev, signatureModal: true }));
  };

  const closeSignatureModal = () => {
    setModalState(prev => ({ ...prev, signatureModal: false }));
    setSignatureSigner(null);
  };

  const openCompleteLessonModal = (expectedFee: number) => {
    setFeePaid(expectedFee.toString());
    setModalState(prev => ({ ...prev, completeLessonModal: true }));
  };

  const closeCompleteLessonModal = () => {
    setModalState(prev => ({ ...prev, completeLessonModal: false }));
    resetSignatures();
  };

  const closeAllModals = () => {
    setModalState({
      addLessonModal: false,
      viewEventModal: false,
      editEventModal: false,
      signatureModal: false,
      completeLessonModal: false,
    });
    setSignatureSigner(null);
    resetSignatures();
  };

  return {
    modalState,
    signatureSigner,
    setSignatureSigner,
    teacherSignature,
    studentSignature,
    feePaid,
    setFeePaid,
    setSignature,
    openAddLessonModal,
    closeAddLessonModal,
    openViewEventModal,
    closeViewEventModal,
    openEditEventModal,
    closeEditEventModal,
    openSignatureModal,
    closeSignatureModal,
    openCompleteLessonModal,
    closeCompleteLessonModal,
    closeAllModals,
  };
};
