import React, { useState } from "react";
import {
  ModalOverlayBlur,
  ModalContent,
  ModalClose,
  Label,
  ModalFormGroup,
  ModalInput,
  ModalActions,
  ActionButton,
  StatusBadge
} from "../../Utils/Styled";
import { CalendarEvent } from "../utils/generateCalendarEvents";

interface ViewEventModalProps {
  isOpen: boolean;
  selectedEvent: CalendarEvent | null;
  onDelete: () => void;
  onClose: () => void;
  onEdit: () => void;
  openCompleteLessonModal: (expectedFee: number) => void;
}

const ViewEventModal: React.FC<ViewEventModalProps> = ({
  isOpen,
  selectedEvent,
  onDelete,
  onClose,
  onEdit,
  openCompleteLessonModal,
}) => {
  if (!selectedEvent) return null;

  const formatDateToLocalDatetimeInput = (date: Date) => {
    const pad = (num: number) => num.toString().padStart(2, "0");
    const year = date.getFullYear();
    const month = pad(date.getMonth() + 1);
    const day = pad(date.getDate());
    const hours = pad(date.getHours());
    const minutes = pad(date.getMinutes());
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  if(!isOpen) return null;

  return (
    <ModalOverlayBlur onClick={onClose}>
      <ModalContent onClick={(e) => e.stopPropagation()}>
        <ModalClose onClick={onClose} aria-label="Close modal">
          &times;
        </ModalClose>
        <h2>View Lesson</h2>
          <ModalFormGroup>
            <ModalFormGroup>
              <StatusBadge status={selectedEvent.status ?? "scheduled"}>
                {selectedEvent.status}
              </StatusBadge>
            </ModalFormGroup>
            <ModalFormGroup>
              <Label>Student:</Label>
              <ModalInput
                type="text"
                value={selectedEvent.title}
                disabled={true}
              />
            </ModalFormGroup>
            <ModalFormGroup>
              <Label>Date:</Label>
              <ModalInput
                type="date"
                value={formatDateToLocalDatetimeInput(selectedEvent.start).split('T')[0]}
                disabled={true}
              />
            </ModalFormGroup>
            <ModalFormGroup>
              <Label>Start Time:</Label>
              <ModalInput
                type="time"
                value={formatDateToLocalDatetimeInput(selectedEvent.start).split('T')[1] || '00:00'}
                disabled={true}
              />
            </ModalFormGroup>
            <ModalFormGroup>
              <Label>End Time:</Label>
              <ModalInput
                type="time"
                value={formatDateToLocalDatetimeInput(selectedEvent.end).split('T')[1] || '00:00'}
                disabled={true}
              />
            </ModalFormGroup>
            {selectedEvent.status === "completed" && selectedEvent.resource && (
              <ModalFormGroup>
                <Label>Fee Paid:</Label>
                <ModalInput
                  type="text"
                  value={`$${selectedEvent.resource.actualFee.toFixed(2)}`}
                  disabled={true}
                />
              </ModalFormGroup>
            )}
            <ModalActions>
              {selectedEvent.status === "scheduled" && (
                <ActionButton
                  variant="primary"
                  type="button"
                  onClick={onEdit}
                >
                  Edit
                </ActionButton>
              )}
              {selectedEvent.status === "unacknowledged" && (
                <ActionButton
                  variant="primary"
                  type="button"
                  onClick={() => openCompleteLessonModal(selectedEvent.resource?.expectedFee || 0)}
                >
                  Complete Lesson
                </ActionButton>
              )}
              <ActionButton
                variant="danger"
                type="button"
                onClick={onDelete}
              >
                Delete
              </ActionButton>
              <ActionButton
                variant="secondary"
                type="button"
                onClick={onClose}>
                Cancel
              </ActionButton>
            </ModalActions>
          </ModalFormGroup>
      </ModalContent>
    </ModalOverlayBlur>
  );
};

export default ViewEventModal;
