import React, { ChangeEvent, FormEvent, useState, useEffect } from "react";
import {
  ModalOverlayBlur,
  ModalContent,
  ModalClose,
  Button,
  Label,
  Input,
} from "../../Utils/Styled";
import { CalendarEvent } from "../utils/generateCalendarEvents";

interface EditEventModalProps {
  isOpen: boolean;
  selectedEvent: CalendarEvent | null;
  onSave: (updatedEvent: {
    event: CalendarEvent;
    newStart: Date;
    newEnd: Date;
  }) => void;
  onClose: () => void;
}

const EditEventModal: React.FC<EditEventModalProps> = ({
  isOpen,
  selectedEvent,
  onSave,
  onClose,
}) => {
  const [editStart, setEditStart] = useState("");
  const [editEnd, setEditEnd] = useState("");
  const [editStudent, setEditStudent] = useState("");

  // Initialize form state when modal opens
  useEffect(() => {
    if (selectedEvent) {
      setEditStudent(selectedEvent.title);
      setEditStart(formatDateToLocalDatetimeInput(selectedEvent.start));
      setEditEnd(formatDateToLocalDatetimeInput(selectedEvent.end));
    }
  }, [selectedEvent]);

  if (!selectedEvent) return null;

  const formatDateToLocalDatetimeInput = (date: Date) => {
    const pad = (num: number) => num.toString().padStart(2, "0");
    const year = date.getFullYear();
    const month = pad(date.getMonth() + 1);
    const day = pad(date.getDate());
    const hours = pad(date.getHours());
    const minutes = pad(date.getMinutes());
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  const parseDatetimeLocalInput = (value: string) => {
    return new Date(value);
  };

  const handleCancel = () => {
    onClose();
  };

  const handleSave = (e: FormEvent) => {
    e.preventDefault();
    
    // Validate dates
    const newStart = parseDatetimeLocalInput(editStart);
    const newEnd = parseDatetimeLocalInput(editEnd);

    if (newEnd <= newStart) {
      alert("End time must be after start time");
      return;
    }

    onSave({
      event: selectedEvent,
      newStart,
      newEnd,
    });
  };

  if (!isOpen) return null;

  return (
    <ModalOverlayBlur onClick={onClose}>
      <ModalContent onClick={(e) => e.stopPropagation()}>
        <ModalClose onClick={onClose} aria-label="Close modal">
          &times;
        </ModalClose>
        <h2>Edit Lesson</h2>
        <form onSubmit={handleSave}>
          <div style={{ marginBottom: "12px" }}>
            <div style={{ marginBottom: "12px" }}>
              <Label>Student:</Label>
              <Input
                type="text"
                value={editStudent}
                onChange={(e: ChangeEvent<HTMLInputElement>) => setEditStudent(e.target.value)}
                required
                style={{ width: "90%" }}
              />
            </div>
            <div style={{ marginBottom: "12px" }}>
              <Label>Date:</Label>
              <Input
                type="date"
                value={editStart.split('T')[0]}
                onChange={(e: ChangeEvent<HTMLInputElement>) => {
                  const newDate = e.target.value;
                  const startTimePart = editStart.split('T')[1] || '00:00';
                  const endTimePart = editEnd.split('T')[1] || '00:00';
                  setEditStart(`${newDate}T${startTimePart}`);
                  setEditEnd(`${newDate}T${endTimePart}`);
                }}
                required
                style={{ width: "90%" }}
              />
            </div>
            <div style={{ marginBottom: "12px" }}>
              <Label>Start Time:</Label>
              <Input
                type="time"
                value={editStart.split('T')[1] || '00:00'}
                onChange={(e: ChangeEvent<HTMLInputElement>) => {
                  const datePart = editStart.split('T')[0];
                  const newTime = e.target.value;
                  setEditStart(`${datePart}T${newTime}`);
                }}
                required
                style={{ width: "90%" }}
              />
            </div>
            <div style={{ marginBottom: "12px" }}>
              <Label>End Time:</Label>
              <Input
                type="time"
                value={editEnd.split('T')[1] || '00:00'}
                onChange={(e: ChangeEvent<HTMLInputElement>) => {
                  const datePart = editStart.split('T')[0];
                  const newTime = e.target.value;
                  setEditEnd(`${datePart}T${newTime}`);
                }}
                required
                style={{ width: "90%" }}
              />
            </div>
            <div style={{ marginTop: "20px", textAlign: "right" }}>
              <Button variant="secondary" type="button" onClick={handleCancel}>
                Cancel
              </Button>
              <Button variant="primary" type="submit" style={{ marginLeft: "8px" }}>
                Save
              </Button>
            </div>
          </div>
        </form>
      </ModalContent>
    </ModalOverlayBlur>
  );
};

export default EditEventModal;
